function AuthModal({ role, setRole, onClose, onSuccess, onError }) { const [form, setForm] = useState({ username: '', password: '', nickname: '' }); const submit = async e => { e.preventDefault(); try { const data = role === 'teacher' ? await api('/auth/login', { method: 'POST', body: JSON.stringify({ username: form.username, password: form.password }) }) : await api('/student/login', { method: 'POST', body: JSON.stringify({ nickname: form.nickname }) }); onSuccess(data); } catch (e) { onError(e.message); } }; return <div className="auth-overlay"><form className="auth-card" onSubmit={submit}><button type="button" className="close-auth" onClick={onClose}>×</button><p className="eyebrow">ĐĂNG NHẬP</p><h2>Bắt đầu học tập</h2><div className="role-switch"><button type="button" className={role === 'student' ? 'selected' : ''} onClick={() => setRole('student')}>Học sinh</button><button type="button" className={role === 'teacher' ? 'selected' : ''} onClick={() => setRole('teacher')}>Giáo viên</button></div>{role === 'student' ? <label>Nickname<input required minLength="2" value={form.nickname} onChange={e => setForm({ ...form, nickname: e.target.value })} placeholder="Nhập nickname" /></label> : <><label>Username hoặc email<input required value={form.username} onChange={e => setForm({ ...form, username: e.target.value })} /></label><label>Mật khẩu<input required type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label></>}<Button type="submit">Đăng nhập</Button></form></div>; }
