function AiQuiz({ onError }) { const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Thông hiểu', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [result, setResult] = useState(null); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => setLessons(x.lessons || [])).catch(e => onError(e.message)); }, [form.grade, form.subject]); async function generate(e) { e.preventDefault(); try { setResult(await api('/ai/quiz', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selected }) })); } catch (e) { onError(e.message); } } async function saveQuestion(q) { try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...q, grade: `Lớp ${form.grade}`, subject: form.subject, options: q.options, answer: q.answer }) }); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">AI ASSISTANT</p><h1>Tạo câu hỏi bằng AI</h1><form className="panel form-grid" onSubmit={generate}><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Cấp độ" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" value={form.count} onChange={e => setForm({ ...form, count: e.target.value })} /></label><div className="lesson-picker wide"><strong>Chọn bài trong mục lục (bắt buộc)</strong>{lessons.map(l => <label key={l.id} className="check"><input type="checkbox" checked={selected.includes(l.id)} onChange={e => setSelected(e.target.checked ? [...selected, l.id] : selected.filter(x => x !== l.id))} />{l.title}</label>)}</div><div className="wide"><Button type="submit">✨ Tạo câu hỏi</Button></div></form>{result?.questions?.length > 0 && <div className="question-list"><h2>Câu hỏi AI đã tạo</h2>{result.questions.map((q, i) => <article key={i}><strong>{i + 1}. {q.question}</strong><small>{q.options.join(' · ')}</small><button className="text-button" onClick={() => saveQuestion(q)}>Lưu vào kho</button></article>)}</div>}</section>; }
function QuizSets({ onError }) { const [items, reload] = useLoad('/quiz-sets'); const [questions, setQuestions] = useState([]); const [form, setForm] = useState({ title: '', description: '', subject: '', grade: '', level: '', timeLimitSeconds: 30, questionIds: [] }); const [open, setOpen] = useState(false); useEffect(() => { api('/questions').then(x => setQuestions(x.items || [])).catch(e => onError(e.message)); }, [open]); async function save(e) { e.preventDefault(); try { await api('/quiz-sets', { method: 'POST', body: JSON.stringify(form) }); setOpen(false); setForm({ ...form, title: '', questionIds: [] }); reload(); } catch (e) { onError(e.message); } } async function remove(id) { try { await api(`/quiz-sets/${id}`, { method: 'DELETE' }); reload(); } catch (e) { onError(e.message); } } return <section className="content-page"><div className="title"><div><p className="eyebrow">THƯ VIỆN ĐỀ</p><h1>Bộ quiz của tôi</h1></div><Button onClick={() => setOpen(!open)}>+ Tạo bộ quiz</Button></div>{open && <form className="panel form-grid" onSubmit={save}><label className="field wide">Tên bộ quiz<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><label className="field wide">Mô tả<textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option value="">Tất cả môn</option><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}><option value="">Tất cả khối</option>{grades.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Thời gian/câu (giây)<input type="number" min="10" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: e.target.value })} /></label><div className="question-picker wide"><strong>Chọn câu hỏi từ kho ({form.questionIds.length})</strong>{questions.map(q => <label className="check" key={q.id}><input type="checkbox" checked={form.questionIds.includes(q.id)} onChange={e => setForm({ ...form, questionIds: e.target.checked ? [...form.questionIds, q.id] : form.questionIds.filter(id => id !== q.id) })} />{q.question} <small>{q.subject} · {q.grade}</small></label>)}</div><div className="wide"><Button type="submit">Lưu bộ quiz</Button></div></form>}<div className="question-list">{items.items?.map(q => <article key={q.id}><strong>{q.title}</strong><small>{q.questionCount} câu · {q.subject || 'Chưa phân loại'} · {q.grade || 'Mọi khối'}</small><button className="text-button danger" onClick={() => remove(q.id)}>Xóa</button></article>)}{!items.items?.length && <div className="empty">Chưa có bộ quiz.</div>}</div></section>; }
function Classes({ onError }) { const [data, reload] = useLoad('/classes'); const [form, setForm] = useState({ name: '', grade: 'Lớp 4', subject: 'Toán học' }); const [selected, setSelected] = useState(null); const [members, setMembers] = useState([]); async function create(e) { e.preventDefault(); try { await api('/classes', { method: 'POST', body: JSON.stringify(form) }); setForm({ ...form, name: '' }); reload(); } catch (e) { onError(e.message); } } async function showMembers(id) { setSelected(id); try { setMembers((await api(`/classes/members?classId=${id}`)).items || []); } catch (e) { onError(e.message); } } async function status(studentId, next) { try { await api('/classes/members/status', { method: 'POST', body: JSON.stringify({ classId: selected, studentId, status: next }) }); showMembers(selected); } catch (e) { onError(e.message); } } return <section className="content-page"><div className="title"><div><p className="eyebrow">CỘNG ĐỒNG LỚP HỌC</p><h1>Lớp học</h1></div></div><form className="panel inline-form" onSubmit={create}><input required placeholder="Tên lớp" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /><select value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{grades.map(x => <option key={x}>{x}</option>)}</select><select value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></select><Button type="submit">+ Tạo lớp</Button></form><div className="question-list">{data.items?.map(c => <article key={c.id}><strong>{c.name}</strong><small>{c.grade} · {c.subject} · {c.studentCount} học sinh · Mã mời: <b>{c.inviteCode}</b></small><button className="text-button" onClick={() => showMembers(c.id)}>Quản lý thành viên</button></article>)}</div>{selected && <div className="panel"><h2>Yêu cầu tham gia</h2>{members.map(m => <div className="member-row" key={m.studentId}><span>{m.nickname}</span><small>{m.status}</small>{m.status === 'pending' && <><button className="text-button" onClick={() => status(m.studentId, 'accepted')}>Duyệt</button><button className="text-button danger" onClick={() => status(m.studentId, 'rejected')}>Từ chối</button></>}</div>)}</div>}</section>; }
function Assignments({ onError }) { const [items, reload] = useLoad('/assignments'); const [quizzes, setQuizzes] = useState([]); const [classes, setClasses] = useState([]); const [form, setForm] = useState({ title: '', quizId: '', classId: '', dueAt: '' }); const [results, setResults] = useState(null); useEffect(() => { api('/quiz-sets').then(x => setQuizzes(x.items || [])).catch(() => {}); api('/classes').then(x => setClasses(x.items || [])).catch(() => {}); }, []); async function save(e) { e.preventDefault(); try { await api('/assignments', { method: 'POST', body: JSON.stringify(form) }); setForm({ ...form, title: '' }); reload(); } catch (e) { onError(e.message); } } async function publish(id, status) { try { await api(`/assignments/${id}/status`, { method: 'POST', body: JSON.stringify({ status }) }); reload(); } catch (e) { onError(e.message); } } async function showResults(id) { try { setResults((await api(`/assignments/${id}/results`)).items); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">BÀI TẬP</p><h1>Giao bài tập quiz</h1><form className="panel form-grid" onSubmit={save}><label className="field">Tên bài giao<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><Select label="Bộ quiz" required value={form.quizId} onChange={e => setForm({ ...form, quizId: e.target.value })}><option value="">Chọn bộ quiz</option>{quizzes.map(q => <option key={q.id} value={q.id}>{q.title}</option>)}</Select><Select label="Lớp học" required value={form.classId} onChange={e => setForm({ ...form, classId: e.target.value })}><option value="">Chọn lớp</option>{classes.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</Select><label className="field">Hạn nộp<input type="datetime-local" value={form.dueAt} onChange={e => setForm({ ...form, dueAt: e.target.value })} /></label><div className="wide"><Button type="submit">Tạo bài tập</Button></div></form><div className="question-list">{items.items?.map(a => <article key={a.id}><strong>{a.title}</strong><small>{a.quizTitle} · {a.className} · {a.submissionCount} bài nộp · {a.computedStatus}</small><button className="text-button" onClick={() => publish(a.id, a.status === 'published' ? 'closed' : 'published')}>{a.status === 'published' ? 'Đóng bài' : 'Giao bài'}</button><button className="text-button" onClick={() => showResults(a.id)}>Xem kết quả</button></article>)}</div>{results && <div className="panel"><h2>Kết quả học sinh</h2>{results.map(x => <div className="member-row" key={x.id}><span>{x.nickname}</span><span>{x.score}/{x.total} · {x.percentage}%</span></div>)}</div>}</section>; }
function Reports({ onError }) { const [data, setData] = useState(null); useEffect(() => { api('/reports/overview').then(setData).catch(e => onError(e.message)); }, []); return <section className="content-page"><p className="eyebrow">PHÂN TÍCH</p><h1>Báo cáo kết quả</h1><div className="feature-grid report-cards">{[['Câu hỏi', data?.questions], ['Bộ quiz đã giao', data?.assignments], ['Lượt nộp bài', data?.submissions], ['Điểm trung bình', `${data?.average || 0}%`], ['Lớp học', data?.classes]].map(([label, value]) => <article key={label}><strong>{value ?? '—'}</strong><small>{label}</small></article>)}</div></section>; }
function JoinClass({ onError, student }) { const [code, setCode] = useState(''); async function submit(e) { e.preventDefault(); if (!student) return onError('Hãy đăng nhập bằng nickname trước.'); try { await api('/classes/join', { method: 'POST', body: JSON.stringify({ inviteCode: code }) }); setCode(''); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">HỌC SINH</p><h1>Tham gia lớp học</h1><p className="muted-copy">Nhập mã mời do giáo viên cung cấp. Giáo viên sẽ xác nhận yêu cầu của bạn.</p><form className="panel inline-form" onSubmit={submit}><input required value={code} onChange={e => setCode(e.target.value.toUpperCase())} placeholder="Mã mời lớp" /><Button type="submit">Gửi yêu cầu</Button></form></section>; }
function StudentAssignments({ onError, student }) { const [items, setItems] = useState([]); const [active, setActive] = useState(null); const [answers, setAnswers] = useState({}); useEffect(() => { if (student) api('/assignments').then(x => setItems(x.items || [])).catch(e => onError(e.message)); }, [student]); async function open(id) { try { const x = await api(`/assignments/${id}`); setActive(x); } catch (e) { onError(e.message); } } async function submit(e) { e.preventDefault(); try { const x = await api(`/assignments/${active.assignment.id}`, { method: 'POST', body: JSON.stringify({ answers }) }); setActive({ ...active, submitted: x.attempt }); } catch (e) { onError(e.message); } } if (!student) return <section className="content-page"><h1>Bài tập của tôi</h1><p className="muted-copy">Đăng nhập bằng nickname để xem bài được giao.</p></section>; return <section className="content-page"><p className="eyebrow">HỌC SINH</p><h1>Bài tập của tôi</h1>{active ? <form className="panel quiz-taking" onSubmit={submit}><button type="button" className="secondary-button" onClick={() => setActive(null)}>← Quay lại</button><h2>{active.assignment.title}</h2>{active.submitted ? <div className="result-box">Bạn đã nộp bài: <b>{active.submitted.score}/{active.submitted.total} ({active.submitted.percentage}%)</b></div> : <>{active.questions.map((q, i) => <div className="quiz-question" key={q.id}><strong>{i + 1}. {q.question}</strong>{q.options.map((o, index) => <label className="check" key={index}><input type="radio" name={q.id} onChange={() => setAnswers({ ...answers, [q.id]: index })} />{o}</label>)}</div>)}<Button type="submit">Nộp bài</Button></>}</form> : <div className="question-list">{items.map(a => <article key={a.id}><strong>{a.title}</strong><small>{a.quizTitle} · {a.className} · {a.submitted ? 'Đã nộp' : a.expired ? 'Đã quá hạn' : 'Chưa làm'}</small>{!a.submitted && !a.expired && <button className="text-button" onClick={() => open(a.id)}>Làm bài</button>}</article>)}{!items.length && <div className="empty">Chưa có bài tập.</div>}</div>}</section>; }
function StudentRoom({ onError, student }) { const [form, setForm] = useState({ code: '', nickname: student?.nickname || '' }); const [room, setRoom] = useState(null); const [player, setPlayer] = useState(null); const [stream, setStream] = useState(null); const [answerState, setAnswerState] = useState(null); async function join(e) { e.preventDefault(); try { const code = form.code.toUpperCase(); const x = await api(`/rooms/${code}/players`, { method: 'POST', body: JSON.stringify({ nickname: form.nickname }) }); setPlayer(x.player); setRoom(x.room); setAnswerState(null); stream?.close(); const s = new EventSource(`${API}/rooms/${code}/events`); s.addEventListener('room', ev => setRoom(JSON.parse(ev.data))); setStream(s); } catch (e) { onError(e.message); } } async function chooseAnswer(index) { const current = room?.currentQuestionData; if (!player || !current || answerState?.questionIndex === current.index) return; try { const result = await api(`/rooms/${room.code}/answer`, { method: 'POST', body: JSON.stringify({ playerId: player.id, answer: index }) }); setAnswerState({ questionIndex: current.index, index, correct: result.correct, points: result.points }); } catch (e) { onError(e.message); } } useEffect(() => () => stream?.close(), [stream]); useEffect(() => { if (answerState && room?.currentQuestionData?.index !== answerState.questionIndex) setAnswerState(null); }, [room?.currentQuestionData?.index]); return <section className="content-page"><p className="eyebrow">QUIZ REALTIME</p><h1>Tham gia phòng quiz</h1>{!room ? <form className="join-card" onSubmit={join}><label>Mã phòng<input required value={form.code} onChange={e => setForm({ ...form, code: e.target.value })} placeholder="VD: ABC123" /></label><label>Nickname<input required minLength="2" value={form.nickname} onChange={e => setForm({ ...form, nickname: e.target.value })} /></label><Button type="submit">Vào phòng →</Button></form> : <div className="room-card"><div className="room-code">{room.code}</div><h2>{room.title}</h2><p>{room.status === 'lobby' ? 'Đã vào phòng. Chờ giáo viên bắt đầu.' : room.status === 'finished' ? 'Trận chơi đã kết thúc.' : 'Trận chơi đang diễn ra.'}</p><div className="room-players-list">{(room.players || []).map(p => <span key={p.id}>{p.nickname}</span>)}</div>{room.currentQuestionData && <div className="live-question"><strong>{room.currentQuestionData.question}</strong>{room.currentQuestionData.options.map((o, i) => <button type="button" className={answerState?.index === i ? (answerState.correct ? 'answer-choice correct' : 'answer-choice incorrect') : 'answer-choice'} disabled={Boolean(answerState)} onClick={() => chooseAnswer(i)} key={i}>{String.fromCharCode(65 + i)}. {o}</button>)}{answerState && <small className={answerState.correct ? 'answer-feedback correct' : 'answer-feedback incorrect'}>{answerState.correct ? `Chính xác! +${answerState.points} điểm` : 'Chưa chính xác.'}</small>}</div>}</div>}</section>; }
function Realtime({ onError }) { const [form, setForm] = useState({ title: '', quizId: '', questionCount: 10, timeLimitSeconds: 20, subject: 'all', grade: 'all', level: 'all' }); const [quizzes, setQuizzes] = useState([]); const [room, setRoom] = useState(null); const [stream, setStream] = useState(null); useEffect(() => { api('/quiz-sets').then(x => setQuizzes(x.items || [])).catch(e => onError(e.message)); }, []); async function create(e) { e.preventDefault(); try { const x = await api('/rooms', { method: 'POST', body: JSON.stringify({ ...form, questionCount: Number(form.questionCount), timeLimitSeconds: Number(form.timeLimitSeconds) }) }); setRoom(x.room); const s = new EventSource(`${API}/rooms/${x.room.code}/events`); s.addEventListener('room', ev => setRoom(JSON.parse(ev.data))); setStream(s); } catch (e) { onError(e.message); } } async function action(path) { try { const x = await api(`/rooms/${room.code}/${path}`, { method: 'POST' }); setRoom(x.room); } catch (e) { onError(e.message); } } useEffect(() => () => stream?.close(), [stream]); return <section className="content-page"><p className="eyebrow">GIÁO VIÊN</p><h1>Phòng quiz realtime</h1>{!room ? <form className="panel form-grid" onSubmit={create}><label className="field wide">Tên phòng<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><Select label="Bộ quiz có sẵn" required value={form.quizId} onChange={e => { const quiz = quizzes.find(item => item.id === e.target.value); setForm({ ...form, quizId: e.target.value, questionCount: quiz?.questionCount || form.questionCount, subject: quiz?.subject || form.subject, grade: quiz?.grade || form.grade }); }}><option value="">Chọn bộ quiz</option>{quizzes.map(quiz => <option key={quiz.id} value={quiz.id}>{quiz.title} · {quiz.questionCount || 0} câu</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="30" value={form.questionCount} onChange={e => setForm({ ...form, questionCount: e.target.value })} /></label><label className="field">Giây/câu<input type="number" min="10" max="120" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: e.target.value })} /></label><div className="wide"><Button type="submit">Tạo phòng</Button></div></form> : <div className="room-card"><div className="room-code">{room.code}</div><h2>{room.title}</h2><p>{room.players?.length || 0} người chơi · {room.status}</p><div className="room-players-list">{(room.players || []).map(p => <span key={p.id}>{p.nickname}</span>)}</div>{room.status === 'lobby' ? <Button onClick={() => action('start')}>Bắt đầu</Button> : room.status === 'playing' && <Button onClick={() => action('next')}>Câu tiếp theo</Button>}</div>}</section>; }
function PaginatedLessonPicker({ lessons, selected, onChange, label = 'Chọn bài trong mục lục' }) { const [page, setPage] = useState(1); const pageSize = 20; const pageCount = Math.max(1, Math.ceil(lessons.length / pageSize)); const current = lessons.slice((page - 1) * pageSize, page * pageSize); useEffect(() => { setPage(1); }, [lessons]); const currentIds = current.map(item => item.id); const allCurrent = current.length > 0 && currentIds.every(id => selected.includes(id)); const togglePage = () => onChange(allCurrent ? selected.filter(id => !currentIds.includes(id)) : Array.from(new Set([...selected, ...currentIds]))); return <div className="lesson-picker wide"><div className="lesson-picker-head"><strong>{label} ({selected.length}/{lessons.length})</strong><div className="lesson-actions"><button type="button" className="text-button" onClick={togglePage}>{allCurrent ? 'Bỏ chọn trang này' : 'Chọn tất cả trang này'}</button><span className="page-meta">Trang {page}/{pageCount}</span></div></div>{current.map(lesson => <label key={lesson.id} className="check"><input type="checkbox" checked={selected.includes(lesson.id)} onChange={event => onChange(event.target.checked ? [...selected, lesson.id] : selected.filter(id => id !== lesson.id))} />{lesson.title}</label>)}{!current.length && <small>Chưa có bài học phù hợp.</small>}{pageCount > 1 && <div className="lesson-pagination"><button type="button" className="secondary-button" disabled={page === 1} onClick={() => setPage(page - 1)}>← Trang trước</button>{Array.from({ length: pageCount }, (_, index) => index + 1).map(number => <button type="button" key={number} className={number === page ? 'page-button active' : 'page-button'} onClick={() => setPage(number)}>{number}</button>)}<button type="button" className="secondary-button" disabled={page === pageCount} onClick={() => setPage(page + 1)}>Trang sau →</button></div>}</div>; }
function QuestionFormPaginated({ initial, onSaved, onCancel, onError }) { const [form, setForm] = useState(initial || { question: '', subject: 'Toán học', grade: 'Lớp 4', level: 'Dễ', options: ['', '', '', ''], answer: 0, explanation: '', lessonId: '', lessonTitle: '' }); const [lessons, setLessons] = useState([]); useEffect(() => { api(`/curriculum?grade=${encodeURIComponent(form.grade.replace('Lớp ', ''))}&subject=${encodeURIComponent(form.subject)}`).then(x => setLessons(x.lessons || [])).catch(() => {}); }, [form.grade, form.subject]); const save = async e => { e.preventDefault(); try { const data = await api(initial?.id ? `/questions/${initial.id}` : '/questions', { method: initial?.id ? 'PUT' : 'POST', body: JSON.stringify({ ...form, options: form.options.map(x => x.trim()) }) }); onSaved(data); } catch (e) { onError(e.message); } }; return <form className="panel form-grid" onSubmit={save}><h2>{initial ? 'Sửa câu hỏi' : 'Thêm câu hỏi thủ công'}</h2><label className="field wide">Nội dung câu hỏi<textarea required value={form.question} onChange={e => setForm({ ...form, question: e.target.value })} /></label><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{grades.map(x => <option key={x}>{x}</option>)}</Select><Select label="Độ khó" value={form.level} onChange={e => setForm({ ...form, level: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><PaginatedLessonPicker lessons={lessons} selected={form.lessonId ? [form.lessonId] : []} onChange={ids => { const lesson = lessons.find(item => item.id === ids[0]); setForm({ ...form, lessonId: ids[0] || '', lessonTitle: lesson?.title || '' }); }} />{form.options.map((option, i) => <label className="field" key={i}>Đáp án {String.fromCharCode(65 + i)}<input required value={option} onChange={e => { const next = [...form.options]; next[i] = e.target.value; setForm({ ...form, options: next }); }} /></label>)}<Select label="Đáp án đúng" value={form.answer} onChange={e => setForm({ ...form, answer: Number(e.target.value) })}>{form.options.map((_, i) => <option key={i} value={i}>Đáp án {String.fromCharCode(65 + i)}</option>)}</Select><label className="field wide">Giải thích<textarea value={form.explanation} onChange={e => setForm({ ...form, explanation: e.target.value })} /></label><div className="actions wide"><Button type="submit">Lưu câu hỏi</Button>{onCancel && <button type="button" className="secondary-button" onClick={onCancel}>Hủy</button>}</div></form>; }
QuestionForm = QuestionFormPaginated;
const QuizSetsLegacy = QuizSets;
QuizSets = function QuizSets(props) { return <><AutoQuizPanel {...props} /><QuizSetsLegacy {...props} /></>; };
function AiQuizPaginated({ onError }) { const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Dễ', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [result, setResult] = useState(null); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelected([]); }).catch(e => onError(e.message)); }, [form.grade, form.subject]); async function generate(e) { e.preventDefault(); if (!selected.length) return onError('Hãy chọn ít nhất một bài trong mục lục.'); try { setResult(await api('/ai/quiz', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selected }) })); } catch (e) { onError(e.message); } } async function saveQuestion(q) { try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...q, grade: `Lớp ${form.grade}`, subject: form.subject, options: q.options, answer: q.answer }) }); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">AI ASSISTANT</p><h1>Tạo câu hỏi bằng AI</h1><form className="panel form-grid" onSubmit={generate}><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Độ khó" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" value={form.count} onChange={e => setForm({ ...form, count: e.target.value })} /></label><PaginatedLessonPicker lessons={lessons} selected={selected} onChange={setSelected} label="Chọn bài trong mục lục (bắt buộc)" /><div className="wide"><Button type="submit">✨ Tạo câu hỏi</Button></div></form>{result?.questions?.length > 0 && <div className="question-list"><h2>Câu hỏi AI đã tạo</h2>{result.questions.map((q, i) => <article key={i}><strong>{i + 1}. {q.question}</strong><small>{q.options.join(' · ')}</small><button className="text-button" onClick={() => saveQuestion(q)}>Lưu vào kho</button></article>)}</div>}</section>; }
AiQuiz = AiQuizPaginated;
function AutoQuizPanel({ onError }) { const [lessons, setLessons] = useState([]); const [selectedLessons, setSelectedLessons] = useState([]); const [form, setForm] = useState({ title: '', grade: 'Lớp 4', subject: 'Toán học', count: 10, timeLimitSeconds: 30, useAI: true, distribution: { Dễ: 0, Vừa: 0, Khó: 0, 'Nâng cao': 0 } }); const [result, setResult] = useState(null); useEffect(() => { const grade = form.grade.replace('Lớp ', ''); api(`/curriculum?grade=${grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelectedLessons([]); }).catch(e => onError(e.message)); }, [form.grade, form.subject]); const updateDifficulty = (key, value) => setForm({ ...form, distribution: { ...form.distribution, [key]: Math.max(0, Number(value) || 0) } }); async function submit(e) { e.preventDefault(); if (!selectedLessons.length) return onError('Hãy chọn ít nhất một bài trong mục lục.'); try { setResult(await api('/quiz-sets/auto', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selectedLessons, lessonTitles: lessons.filter(item => selectedLessons.includes(item.id)).map(item => item.title) }) })); } catch (e) { onError(e.message); } } return <div className="panel"><div className="title"><div><p className="eyebrow">AI QUIZ BUILDER</p><h2>Tạo bộ quiz tự động</h2></div><span className="page-meta">Chọn bài, độ khó và số lượng câu</span></div><form className="form-grid" onSubmit={submit}><label className="field wide">Tên bộ quiz<input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Ví dụ: Ôn tập giữa kỳ lớp 4" /></label><Select label="Khối lớp (bắt buộc)" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{grades.map(x => <option key={x}>{x}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><label className="field">Tổng số câu<input type="number" min="1" max="50" value={form.count} onChange={e => setForm({ ...form, count: Number(e.target.value) || 1 })} /></label><label className="field">Thời gian/câu<input type="number" min="10" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: Number(e.target.value) || 30 })} /></label><div className="difficulty-grid wide">{levels.map(level => <label className="field" key={level}>{level}<input type="number" min="0" value={form.distribution[level]} onChange={e => updateDifficulty(level, e.target.value)} /></label>)}</div><PaginatedLessonPicker lessons={lessons} selected={selectedLessons} onChange={setSelectedLessons} label="Chọn bài trong mục lục (bắt buộc)" /><label className="check wide"><input type="checkbox" checked={form.useAI} onChange={e => setForm({ ...form, useAI: e.target.checked })} />Dùng AI để chọn câu hỏi phù hợp nhất</label><div className="wide"><Button type="submit">Tạo bộ quiz tự động</Button></div></form>{result && <div className="result-box">Đã tạo bộ quiz với {result.selectedCount} câu ({result.selectionMode === 'ai' ? 'AI lựa chọn' : 'lọc theo quy tắc'}).</div>}</div>; }
function TeacherHomeStitch({ teacher }) { const navigate = useNavigate(); const [questions] = useLoad('/questions'); const [quizzes] = useLoad('/quiz-sets'); const [classes] = useLoad('/classes'); const [assignments] = useLoad('/assignments'); const cards = [{ label: 'Câu hỏi trong kho', value: questions.length, hint: 'Tất cả câu hỏi đã lưu', tone: 'violet', icon: '☷' }, { label: 'Bộ quiz', value: quizzes.items?.length || 0, hint: 'Bộ đề sẵn sàng sử dụng', tone: 'blue', icon: '▤' }, { label: 'Lớp học', value: classes.items?.length || 0, hint: 'Các lớp đang quản lý', tone: 'green', icon: '♧' }, { label: 'Bài tập đã giao', value: assignments.items?.length || 0, hint: 'Theo dõi tiến độ học sinh', tone: 'orange', icon: '↗' }]; return <section className="content-page stitch-dashboard"><div className="dashboard-heading"><div><p className="eyebrow">BẢNG ĐIỀU KHIỂN GIÁO VIÊN</p><h1>Chào {teacher?.displayName || 'giáo viên'} 👋</h1><p className="muted-copy">Tổng quan hoạt động dạy học và các công cụ tạo quiz của bạn.</p></div><button className="secondary-button" onClick={() => window.location.reload()}>↻ Làm mới</button></div><div className="stat-grid">{cards.map(card => <article className={`stat-card ${card.tone}`} key={card.label}><span className="stat-icon">{card.icon}</span><div><small>{card.label}</small><strong>{card.value}</strong><span>{card.hint}</span></div></article>)}</div><div className="dashboard-grid"><article className="dashboard-panel quick-panel"><div className="panel-heading"><div><p className="eyebrow">TẠO NỘI DUNG</p><h2>Bắt đầu nhanh</h2></div><span className="panel-kicker">4 tác vụ</span></div><div className="quick-actions"><button onClick={() => navigate('/teacher/questions')}><span>☷</span><b>Thêm câu hỏi</b><small>Tạo thủ công trong kho</small></button><button onClick={() => navigate('/teacher/questions/ai')}><span>✦</span><b>AI tạo câu hỏi</b><small>Dựa trên mục lục bài học</small></button><button onClick={() => navigate('/teacher/quizzes')}><span>▤</span><b>Tạo bộ quiz</b><small>Chọn câu hỏi phù hợp</small></button><button onClick={() => navigate('/teacher/realtime')}><span>◉</span><b>Mở phòng realtime</b><small>Chơi trực tiếp cùng lớp</small></button></div></article><article className="dashboard-panel activity-panel"><div className="panel-heading"><div><p className="eyebrow">HOẠT ĐỘNG GẦN ĐÂY</p><h2>Bài tập đã giao</h2></div><button className="text-button" onClick={() => navigate('/teacher/assignments')}>Xem tất cả →</button></div>{assignments.items?.slice(0, 4).map(item => <div className="activity-row" key={item.id}><span className="activity-dot" /><div><b>{item.title}</b><small>{item.className} · {item.submissionCount || 0} bài nộp</small></div><span className={`status-pill ${item.computedStatus}`}>{item.computedStatus === 'published' ? 'Đang mở' : item.computedStatus}</span></div>)}{!assignments.items?.length && <div className="empty-state"><span>◌</span><b>Chưa có bài tập</b><small>Giao bài đầu tiên cho lớp học của bạn.</small></div>}</article></div></section>; }
TeacherHome = TeacherHomeStitch;
function RealtimeStitch({ onError }) { const [form, setForm] = useState({ title: '', quizId: '', questionCount: 10, timeLimitSeconds: 20, subject: 'all', grade: 'all', level: 'all' }); const [quizzes, setQuizzes] = useState([]); const [room, setRoom] = useState(null); const [stream, setStream] = useState(null); const [displayTime, setDisplayTime] = useState(0); useEffect(() => { api('/quiz-sets').then(x => setQuizzes(x.items || [])).catch(e => onError(e.message)); }, []); async function create(e) { e.preventDefault(); if (!form.quizId) return onError('Hãy chọn một bộ quiz trước khi tạo phòng.'); try { const x = await api('/rooms', { method: 'POST', body: JSON.stringify({ ...form, questionCount: Number(form.questionCount), timeLimitSeconds: Number(form.timeLimitSeconds) }) }); setRoom(x.room); const s = new EventSource(`${API}/rooms/${x.room.code}/events`); s.addEventListener('room', event => setRoom(JSON.parse(event.data))); setStream(s); } catch (e) { onError(e.message); } } async function action(path) { try { const x = await api(`/rooms/${room.code}/${path}`, { method: 'POST' }); setRoom(x.room); } catch (e) { onError(e.message); } } useEffect(() => () => stream?.close(), [stream]); useEffect(() => { setDisplayTime(Number(room?.timeRemaining ?? form.timeLimitSeconds) || 0); if (!room || room.status !== 'playing') return; const timer = window.setInterval(() => setDisplayTime(value => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [room?.status, room?.currentQuestionData?.index]); if (!room) return <section className="content-page setup-page"><div className="dashboard-heading"><div><p className="eyebrow">PHÒNG THI REALTIME</p><h1>Chuẩn bị phòng đấu trực tiếp</h1><p className="muted-copy">Thiết lập một trận quiz tương tác và theo dõi học sinh theo thời gian thực.</p></div><span className="setup-badge">● Phòng mới</span></div><form className="setup-layout" onSubmit={create}><div className="setup-main"><article className="dashboard-panel setup-card"><div className="panel-heading"><h2>① Nội dung phòng</h2><span className="panel-kicker">Bắt buộc</span></div><label className="field wide">Tên phòng<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Ví dụ: Ôn tập Toán lớp 4" /></label><Select label="Bộ quiz có sẵn" required value={form.quizId} onChange={e => { const quiz = quizzes.find(item => item.id === e.target.value); setForm({ ...form, quizId: e.target.value, questionCount: quiz?.questionCount || form.questionCount, subject: quiz?.subject || form.subject, grade: quiz?.grade || form.grade }); }}><option value="">Chọn bộ quiz</option>{quizzes.map(quiz => <option key={quiz.id} value={quiz.id}>{quiz.title} · {quiz.questionCount || 0} câu</option>)}</Select><div className="form-grid"><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}><option value="all">Tất cả khối</option>{grades.map(x => <option key={x}>{x}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option value="all">Tất cả môn</option><option>Toán học</option><option>Tiếng Việt</option></Select></div></article><article className="dashboard-panel setup-card"><div className="panel-heading"><h2>② Cài đặt trận đấu</h2><span className="panel-kicker">Tùy chỉnh</span></div><div className="mode-options"><label className="mode-option selected"><input type="radio" checked readOnly /><b>Chế độ realtime</b><small>Học sinh trả lời cùng lúc, có bảng xếp hạng trực tiếp.</small></label><label className="mode-option"><input type="radio" readOnly /><b>Chế độ luyện tập</b><small>Mỗi học sinh làm theo tốc độ riêng.</small></label></div><div className="form-grid compact-grid"><label className="field">Số câu<input type="number" min="1" max="30" value={form.questionCount} onChange={e => setForm({ ...form, questionCount: e.target.value })} /></label><label className="field">Giây/câu<input type="number" min="10" max="120" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: e.target.value })} /></label></div></article><button className="primary-button setup-submit" type="submit" disabled={!form.quizId}>Tạo phòng và nhận mã →</button></div><aside className="setup-preview dashboard-panel"><span className="preview-label">XEM TRƯỚC PHÒNG</span><div className="preview-code">842 195</div><b>{form.quizId ? quizzes.find(item => item.id === form.quizId)?.title || 'Bộ quiz đã chọn' : 'Chưa chọn bộ quiz'}</b><small>Học sinh tham gia bằng mã hiển thị sau khi tạo.</small><div className="preview-line"><span>Thời lượng</span><b>{form.timeLimitSeconds}s/câu</b></div><div className="preview-line"><span>Số câu</span><b>{form.questionCount} câu</b></div></aside></form></section>; return <section className="content-page realtime-page"><div className="live-header"><div><p className="eyebrow">QUIZ LIVE ARENA <span className="live-dot">● ĐANG TRỰC TIẾP</span></p><h1>{room.title}</h1></div><div className="live-code-box"><small>MÃ PHÒNG THI</small><strong>{room.code}</strong></div><button className="secondary-button" onClick={() => { stream?.close(); setRoom(null); }}>Kết thúc phòng</button></div><div className="live-layout"><div className="live-stage"><div className="live-question-head"><span>Câu hỏi {Math.min((room.currentQuestion || 0) + 1, 30)} / {room.questionCount || form.questionCount}</span><b>{displayTime}s</b></div>{room.currentQuestionData ? <div className="live-question-card"><p className="live-question-number">CÂU HỎI HIỆN TẠI</p><h2>{room.currentQuestionData.question}</h2><div className="live-answer-grid">{room.currentQuestionData.options?.map((option, index) => <div className={`live-answer answer-${index}`} key={index}><b>{String.fromCharCode(65 + index)}</b><span>{option}</span></div>)}</div></div> : <div className="live-empty"><span>◉</span><h2>Sẵn sàng bắt đầu?</h2><p>Chia sẻ mã phòng <b>{room.code}</b> cho học sinh rồi bắt đầu trận đấu.</p></div>}<div className="live-controls"><button className="secondary-button" onClick={() => action('start')} disabled={room.status !== 'lobby'}>▶ Bắt đầu</button><button className="primary-button" onClick={() => action('next')} disabled={room.status !== 'playing'}>Câu tiếp theo →</button></div></div><aside className="live-sidebar"><article className="leaderboard-card"><div className="panel-heading"><h2>🏆 Bảng xếp hạng</h2><span className="panel-kicker">Top 5</span></div>{room.leaderboard?.slice(0, 5).map((player, index) => <div className="leader-row" key={player.id}><b>{index + 1}</b><span>{player.nickname}</span><strong>{player.score || 0}</strong></div>)}{!room.leaderboard?.length && <div className="empty-state compact"><span>◌</span><small>Chưa có người chơi</small></div>}</article><article className="players-card"><div className="panel-heading"><h2>Danh sách phòng thi</h2><span className="live-dot">● {room.players?.length || 0} người</span></div><div className="player-chips">{room.players?.map(player => <span key={player.id}>{player.nickname}</span>)}</div></article></aside></div></section>; }
Realtime = RealtimeStitch;
const questionSchema = z.object({ question: z.string().trim().min(1, 'Nhập nội dung câu hỏi.'), subject: z.string().min(1), grade: z.string().min(1), level: z.string().min(1), options: z.array(z.string().trim().min(1, 'Không được để trống đáp án.')).length(4), answer: z.coerce.number().min(0).max(3), explanation: z.string().optional(), lessonId: z.string().min(1, 'Hãy chọn một bài trong mục lục.') });
function QuestionFormRHF({ initial, onSaved, onCancel, onError }) { const defaults = initial || { question: '', subject: 'Toán học', grade: 'Lớp 4', level: 'Dễ', options: ['', '', '', ''], answer: 0, explanation: '', lessonId: '', lessonTitle: '' }; const { register, handleSubmit, setValue, watch, formState: { errors, isSubmitting } } = useForm({ resolver: zodResolver(questionSchema), defaultValues: defaults }); const [lessons, setLessons] = useState([]); const grade = watch('grade'); const subject = watch('subject'); const selectedLesson = watch('lessonId'); useEffect(() => { api(`/curriculum?grade=${encodeURIComponent(grade.replace('Lớp ', ''))}&subject=${encodeURIComponent(subject)}`).then(x => setLessons(x.lessons || [])).catch(e => onError(e.message)); }, [grade, subject]); async function save(values) { try { const lesson = lessons.find(item => item.id === values.lessonId); await api(initial?.id ? `/questions/${initial.id}` : '/questions', { method: initial?.id ? 'PUT' : 'POST', body: JSON.stringify({ ...values, lessonTitle: lesson?.title || initial?.lessonTitle || '' }) }); toast.success(initial ? 'Đã cập nhật câu hỏi' : 'Đã thêm câu hỏi vào kho'); onSaved(); } catch (error) { onError(error.message); } } return <form className="panel form-grid ant-question-form" onSubmit={handleSubmit(save)}><div className="wide form-heading"><div><p className="eyebrow">QUESTION EDITOR</p><h2>{initial ? 'Sửa câu hỏi' : 'Thêm câu hỏi thủ công'}</h2></div><AntTag color="purple">React Hook Form · Zod</AntTag></div><label className="field wide">Nội dung câu hỏi<textarea {...register('question')} />{errors.question && <small className="form-error">{errors.question.message}</small>}</label><label className="field">Môn học<select {...register('subject')}><option>Toán học</option><option>Tiếng Việt</option></select></label><label className="field">Khối lớp<select {...register('grade')}>{grades.map(item => <option key={item}>{item}</option>)}</select></label><label className="field">Độ khó<select {...register('level')}>{levels.map(item => <option key={item}>{item}</option>)}</select></label><div className="wide"><PaginatedLessonPicker lessons={lessons} selected={selectedLesson ? [selectedLesson] : []} onChange={ids => { const id = ids[ids.length - 1] || ''; setValue('lessonId', id, { shouldValidate: true }); setValue('lessonTitle', lessons.find(item => item.id === id)?.title || ''); }} label="Chọn bài trong mục lục (bắt buộc)" />{errors.lessonId && <small className="form-error">{errors.lessonId.message}</small>}</div>{[0, 1, 2, 3].map(index => <label className="field" key={index}>Đáp án {String.fromCharCode(65 + index)}<input {...register(`options.${index}`)} />{errors.options?.[index] && <small className="form-error">{errors.options[index].message}</small>}</label>)}<label className="field">Đáp án đúng<select {...register('answer')}><option value="0">Đáp án A</option><option value="1">Đáp án B</option><option value="2">Đáp án C</option><option value="3">Đáp án D</option></select></label><label className="field wide">Giải thích<textarea {...register('explanation')} /></label><div className="actions wide"><AntButton type="primary" htmlType="submit" loading={isSubmitting}>Lưu câu hỏi</AntButton>{onCancel && <AntButton htmlType="button" onClick={onCancel}>Hủy</AntButton>}</div></form>; }
QuestionForm = QuestionFormRHF;
function ReportsStitch({ onError }) { const [data, setData] = useState(null); useEffect(() => { api('/reports/overview').then(setData).catch(e => onError(e.message)); }, []); const points = data?.trend || [{ name: 'T1', value: data?.average || 0 }, { name: 'T2', value: data?.average || 0 }, { name: 'T3', value: data?.average || 0 }, { name: 'T4', value: data?.average || 0 }]; const columns = [{ title: 'Chỉ số', dataIndex: 'label', key: 'label' }, { title: 'Giá trị', dataIndex: 'value', key: 'value', render: value => <b>{value}</b> }, { title: 'Trạng thái', key: 'status', render: () => <AntTag color="green">Đang cập nhật</AntTag> }]; const rows = [['Câu hỏi trong kho', data?.questions || 0], ['Bộ quiz đã giao', data?.assignments || 0], ['Lượt nộp bài', data?.submissions || 0], ['Lớp học', data?.classes || 0]].map(([label, value]) => ({ key: label, label, value })); return <section className="content-page reports-page"><div className="dashboard-heading"><div><p className="eyebrow">PHÂN TÍCH HỌC TẬP</p><h1>Thống kê đào tạo</h1><p className="muted-copy">Theo dõi hoạt động câu hỏi, bộ quiz và kết quả học sinh.</p></div><AntButton onClick={() => window.location.reload()}>↻ Làm mới</AntButton></div><div className="stat-grid report-stat-grid"><AntCard><Statistic title="Câu hỏi trong kho" value={data?.questions || 0} prefix={<BookOpen size={18} />} /></AntCard><AntCard><Statistic title="Bộ quiz đã giao" value={data?.assignments || 0} prefix={<ClipboardList size={18} />} /></AntCard><AntCard><Statistic title="Lượt nộp bài" value={data?.submissions || 0} prefix={<Users size={18} />} /></AntCard><AntCard><Statistic title="Điểm trung bình" value={data?.average || 0} suffix="%" /></AntCard></div><div className="reports-grid"><AntCard title="Xu hướng điểm trung bình"><ResponsiveContainer width="100%" height={250}><AreaChart data={points}><defs><linearGradient id="scoreGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#4f46e5" stopOpacity={0.28}/><stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" stroke="#e2e7ff"/><XAxis dataKey="name"/><YAxis/><ChartTooltip/><Area type="monotone" dataKey="value" stroke="#4f46e5" fill="url(#scoreGradient)" strokeWidth={3}/></AreaChart></ResponsiveContainer></AntCard><AntCard title="Tổng quan dữ liệu"><AntTable columns={columns} dataSource={rows} pagination={false} size="small" /></AntCard></div></section>; }
Reports = ReportsStitch;
function StudentRoomStitch({ onError, student }) { const [form, setForm] = useState({ code: '', nickname: student?.nickname || '' }); const [room, setRoom] = useState(null); const [player, setPlayer] = useState(null); const [stream, setStream] = useState(null); const [answerState, setAnswerState] = useState(null); const [displayTime, setDisplayTime] = useState(0); async function join(e) { e.preventDefault(); try { const code = form.code.toUpperCase(); const x = await api(`/rooms/${code}/players`, { method: 'POST', body: JSON.stringify({ nickname: form.nickname }) }); setPlayer(x.player); setRoom(x.room); setAnswerState(null); stream?.close(); const source = new EventSource(`${API}/rooms/${code}/events`); source.addEventListener('room', event => setRoom(JSON.parse(event.data))); setStream(source); toast.success('Đã vào phòng quiz'); } catch (error) { onError(error.message); } } async function chooseAnswer(index) { const current = room?.currentQuestionData; if (!player || !current || answerState?.questionIndex === current.index) return; setAnswerState({ questionIndex: current.index, index, pending: true }); try { const result = await api(`/rooms/${room.code}/answer`, { method: 'POST', body: JSON.stringify({ playerId: player.id, answer: index }) }); setAnswerState({ questionIndex: current.index, index, correct: result.correct, points: result.points }); } catch (error) { setAnswerState(null); onError(error.message); } } useEffect(() => () => stream?.close(), [stream]); useEffect(() => { setDisplayTime(Number(room?.timeRemaining ?? 0) || 0); if (!room || room.status !== 'playing') return; const timer = window.setInterval(() => setDisplayTime(value => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [room?.status, room?.currentQuestionData?.index]); useEffect(() => { if (answerState && room?.currentQuestionData?.index !== answerState.questionIndex) setAnswerState(null); }, [room?.currentQuestionData?.index]); return <section className="content-page student-lobby-page"><div className="dashboard-heading"><div><p className="eyebrow">STUDENT LOBBY</p><h1>Phòng chờ thi đấu</h1><p className="muted-copy">Nhập mã phòng hoặc quét QR để tham gia cùng lớp.</p></div><AntTag color="green">● SSE realtime</AntTag></div>{!room ? <motion.form initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="join-card lobby-join-card" onSubmit={join}><div className="join-card-icon"><Radio size={26}/></div><h2>Tham gia phòng quiz</h2><label>Mã phòng<input required value={form.code} onChange={e => setForm({ ...form, code: e.target.value.toUpperCase() })} placeholder="VD: 849201" /></label><label>Nickname<input required minLength="2" value={form.nickname} onChange={e => setForm({ ...form, nickname: e.target.value })} placeholder="Tên hiển thị của bạn" /></label><AntButton type="primary" htmlType="submit" block>Vào phòng →</AntButton></motion.form> : <motion.div initial={{ opacity: 0, scale: .98 }} animate={{ opacity: 1, scale: 1 }} className="student-room-grid"><article className="dashboard-panel qr-panel"><p className="eyebrow">MÃ PHÒNG THAM GIA</p><div className="student-room-code">{room.code}</div><QRCodeSVG value={`${window.location.origin}/student/room?code=${room.code}`} size={180} bgColor="#ffffff" fgColor="#312e81" level="M" /><small>Quét mã bằng camera điện thoại để vào nhanh.</small><button className="secondary-button" onClick={() => navigator.clipboard?.writeText(room.code)}>Sao chép mã phòng</button></article><article className="dashboard-panel lobby-players"><div className="panel-heading"><div><p className="eyebrow">PHÒNG CHỜ</p><h2>{room.title}</h2></div><AntTag color="green">{room.players?.length || 0} người chơi</AntTag></div><p className="muted-copy">{room.status === 'lobby' ? 'Đã vào phòng. Chờ giáo viên bắt đầu trận đấu.' : room.status === 'finished' ? 'Trận đấu đã kết thúc.' : 'Trận đấu đang diễn ra.'}</p><div className="player-chips light-player-chips">{room.players?.map(player => <span key={player.id}>{player.nickname}</span>)}</div>{room.currentQuestionData && <div className="live-question-card student-question"><p className="live-question-number">CÂU HỎI HIỆN TẠI <span className="student-timer">⏱ {displayTime}s</span></p><h2>{room.currentQuestionData.question}</h2>{room.currentQuestionData.options?.map((option, index) => <button type="button" className={`student-answer ${answerState?.index === index ? (answerState.pending ? 'selected' : answerState.correct ? 'correct' : 'incorrect') : ''}`} disabled={Boolean(answerState) || displayTime <= 0} onClick={() => chooseAnswer(index)} key={index}><b>{String.fromCharCode(65 + index)}</b>{option}</button>)}{answerState && <small className={answerState.correct ? 'answer-feedback correct' : 'answer-feedback incorrect'}>{answerState.correct ? `Chính xác! +${answerState.points} điểm` : 'Chưa chính xác.'}</small>}</div>}</article></motion.div>}</section>; }
StudentRoom = StudentRoomStitch;
function AiQuizI18n({ onError }) { const { t } = useTranslation(); const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Dễ', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [result, setResult] = useState(null); const [isGenerating, setIsGenerating] = useState(false); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelected([]); }).catch(e => onError(e.message)); }, [form.grade, form.subject]); async function generate(event) { event.preventDefault(); if (!selected.length) return onError(t('ai.selectLesson')); setIsGenerating(true); setResult(null); try { const response = await api('/ai/quiz', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selected }) }); setResult(response); toast.success(t('ai.generate')); } catch (error) { onError(error.message || t('common.requestFailed')); } finally { setIsGenerating(false); } } async function saveQuestion(question) { try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...question, grade: `Lớp ${form.grade}`, subject: form.subject, options: question.options, answer: question.answer }) }); toast.success(t('common.save')); } catch (error) { onError(error.message || t('common.requestFailed')); } } return <section className="content-page"><p className="eyebrow">AI ASSISTANT</p><h1>{t('ai.title')}</h1><form className="panel form-grid" onSubmit={generate}>{isGenerating && <div className="ai-generation-status wide"><span className="ai-loader"/><div><b>{t('ai.generating')}</b><small>{t('ai.generatingHint')}</small></div></div>}<Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Độ khó" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" value={form.count} disabled={isGenerating} onChange={e => setForm({ ...form, count: e.target.value })} /></label><PaginatedLessonPicker lessons={lessons} selected={selected} onChange={setSelected} label={t('ai.selectLesson')} /><div className="wide"><AntButton type="primary" htmlType="submit" loading={isGenerating} disabled={!selected.length}>{isGenerating ? t('ai.generating') : `✨ ${t('ai.generate')}`}</AntButton></div></form>{result?.questions?.length > 0 && <div className="question-list"><h2>Câu hỏi AI đã tạo</h2>{result.questions.map((question, index) => <article key={index}><strong>{index + 1}. {question.question}</strong><small>{question.options.join(' · ')}</small><button className="text-button" onClick={() => saveQuestion(question)}>{t('common.save')}</button></article>)}</div>}</section>; }
AiQuiz = AiQuizI18n;
function AiQuizStream({ onError }) { const { t } = useTranslation(); const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Dễ', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [run, setRun] = useState(null); const [savedJobs, setSavedJobs] = useState([]); const [approvedJobs, setApprovedJobs] = useState([]); const [starting, setStarting] = useState(false); const streamRef = useRef(null); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelected([]); }).catch(error => onError(error.message)); }, [form.grade, form.subject]); useEffect(() => () => streamRef.current?.close(), []); function updateJob(jobId, patch) { setRun(previous => previous ? { ...previous, jobs: previous.jobs.map(job => job.id === jobId ? { ...job, ...patch } : job) } : previous); } function connect(runId) { streamRef.current?.close(); const source = new EventSource(`${API}/ai/quiz/runs/${runId}/stream`); streamRef.current = source; const parse = event => { try { return JSON.parse(event.data); } catch { return null; } }; source.addEventListener('run.snapshot', event => setRun(parse(event))); source.addEventListener('run.started', event => setRun(previous => ({ ...(previous || {}), ...(parse(event) || {}) }))); source.addEventListener('question.started', event => { const data = parse(event); if (data) updateJob(data.jobId, { status: 'generating', attempts: data.attempt }); }); source.addEventListener('question.retrying', event => { const data = parse(event); if (data) updateJob(data.jobId, { status: 'retrying', attempts: data.attempt, error: data.error }); }); source.addEventListener('question.completed', event => { const data = parse(event); if (data) { updateJob(data.jobId, { status: 'completed', attempts: data.attempt, question: data.question, error: null }); setRun(previous => previous ? { ...previous, completedCount: (previous.completedCount || 0) + 1 } : previous); } }); source.addEventListener('question.failed', event => { const data = parse(event); if (data) { updateJob(data.jobId, { status: 'failed', attempts: data.attempt, error: data.error }); setRun(previous => previous ? { ...previous, failedCount: (previous.failedCount || 0) + 1 } : previous); } }); source.addEventListener('run.progress', event => setRun(parse(event))); source.addEventListener('run.completed', event => { setRun(parse(event)); source.close(); }); source.addEventListener('run.failed', event => { setRun(parse(event)); source.close(); }); source.onerror = () => { if (run?.status !== 'completed' && run?.status !== 'failed') onError('Kết nối stream bị gián đoạn. Hãy mở lại phiên để đồng bộ tiến độ.'); }; } async function start(event) { event.preventDefault(); if (!selected.length) return onError(t('ai.selectLesson')); setStarting(true); try { const created = await api('/ai/quiz/runs', { method: 'POST', body: JSON.stringify({ ...form, count: Number(form.count), lessonIds: selected }) }); setRun(created); connect(created.runId); } catch (error) { onError(error.message); } finally { setStarting(false); } } async function retry(jobId) { try { await api(`/ai/quiz/runs/${run.runId}/jobs/${jobId}/retry`, { method: 'POST' }); updateJob(jobId, { status: 'generating', error: null }); if (!streamRef.current || streamRef.current.readyState === EventSource.CLOSED) connect(run.runId); } catch (error) { onError(error.message); } } function toggleApproval(jobId) { setApprovedJobs(previous => previous.includes(jobId) ? previous.filter(id => id !== jobId) : [...previous, jobId]); } async function saveJob(job) { if (!job.question || !approvedJobs.includes(job.id) || savedJobs.includes(job.id)) return; try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...job.question, subject: job.question.subject || run.subject, grade: job.question.grade || `Lớp ${run.grade}`, level: job.question.level || run.difficulty, lessonId: job.lessonId || '', lessonTitle: job.lessonTitle || job.question.lesson || job.question.lessonTitle || '' }) }); setSavedJobs(previous => [...previous, job.id]); toast.success('Đã lưu câu hỏi vào kho.'); } catch (error) { onError(error.message); } } async function saveAll() { const pending = (run?.jobs || []).filter(job => job.question && approvedJobs.includes(job.id) && !savedJobs.includes(job.id)); await Promise.all(pending.map(saveJob)); } return <section className="content-page"><p className="eyebrow">AI ASSISTANT · STREAM RUN</p><h1>{t('ai.title')}</h1><form className="panel form-grid" onSubmit={start}><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Độ khó" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" disabled={starting} value={form.count} onChange={e => setForm({ ...form, count: e.target.value })} /></label><PaginatedLessonPicker lessons={lessons} selected={selected} onChange={setSelected} label={t('ai.selectLesson')} /><div className="wide"><AntButton type="primary" htmlType="submit" loading={starting} disabled={Boolean(run)}>{starting ? 'Đang mở phiên...' : `✨ ${t('ai.generate')}`}</AntButton></div></form>{run && <div className="ai-run-layout"><article className="dashboard-panel ai-run-summary"><div className="panel-heading"><div><p className="eyebrow">AI GENERATION RUN</p><h2>Đang tạo {run.requestedCount} câu hỏi</h2></div><AntTag color={run.status === 'completed' ? 'green' : run.status === 'failed' ? 'red' : 'blue'}>{run.status}</AntTag></div><div className="ai-progress"><AntProgress percent={Math.round(((run.completedCount || 0) + (run.failedCount || 0)) / run.requestedCount * 100)} status={run.status === 'failed' ? 'exception' : 'active'} /><small>Đã xử lý {(run.completedCount || 0) + (run.failedCount || 0)}/{run.requestedCount} · Thành công {run.completedCount || 0} · Lỗi {run.failedCount || 0}</small>{run.jobs?.some(job => job.question && approvedJobs.includes(job.id) && !savedJobs.includes(job.id)) && <AntButton size="small" onClick={saveAll}>Lưu tất cả câu đã duyệt</AntButton>}</div><div className="ai-job-list">{run.jobs?.map(job => <article className={`ai-job ${job.status}`} key={job.id}><span className="ai-job-index">{job.position}</span><div>{job.question ? <><b>{job.question.question}</b>{job.lessonTitle && <small>Bài: {job.lessonTitle}</small>}<small>{job.question.options?.join(' · ')}</small></> : <><b>{job.status === 'retrying' ? 'Đang thử lại câu hỏi…' : job.status === 'generating' ? 'Đang tạo câu hỏi…' : job.status === 'failed' ? 'Tạo câu hỏi thất bại' : 'Đang chờ xử lý'}</b><small>{job.error || `Lần thử ${job.attempts || 0}`}</small></>}</div><div>{job.status === 'completed' ? (savedJobs.includes(job.id) ? <AntTag color="green">Đã lưu</AntTag> : approvedJobs.includes(job.id) ? <><AntTag color="blue">Đã duyệt</AntTag><AntButton size="small" type="text" onClick={() => toggleApproval(job.id)}>Bỏ duyệt</AntButton></> : <AntButton size="small" onClick={() => toggleApproval(job.id)}>Duyệt câu</AntButton>) : job.status === 'failed' ? <AntButton size="small" onClick={() => retry(job.id)}>Tạo lại</AntButton> : <span className="ai-job-spinner" />}</div></article>)}</div>{['completed', 'failed'].includes(run.status) && <AntButton onClick={() => { streamRef.current?.close(); setRun(null); setSelected([]); setSavedJobs([]); setApprovedJobs([]); }}>Tạo phiên mới</AntButton>}</article></div>}</section>; }
AiQuiz = AiQuizStream;
function RoleGuard({ teacher, children }) { return teacher ? children : <Navigate to="/student" replace />; }
function ModuleLink({ to, children, end = false }) { return <NavLink to={to} end={end} className={({ isActive }) => `module-link${isActive ? ' active' : ''}`}>{children}</NavLink>; }
function RouterShell({ teacher, student, onAuth, onError }) { const [authOpen, setAuthOpen] = useState(false); const [role, setRole] = useState('student'); const navigate = useNavigate(); const location = useLocation(); const isTeacherArea = location.pathname.startsWith('/teacher'); function openAuth(nextRole) { setRole(nextRole); setAuthOpen(true); } return <div className="app-shell"><aside className="app-sidebar"><div className="brand-lockup"><span className="brand-mark">✦</span><span>quizzz</span></div><div className="brand-caption">HỌC VUI · NHỚ LÂU</div><nav className="module-nav"><div className="nav-group"><div className="nav-heading">HỌC SINH</div><ModuleLink to="/student" end>⌂ <span>Trang chủ</span></ModuleLink><ModuleLink to="/student/room">◉ <span>Phòng realtime</span></ModuleLink><ModuleLink to="/student/assignments">▣ <span>Bài tập của tôi</span></ModuleLink><ModuleLink to="/student/classes">♧ <span>Lớp học</span></ModuleLink></div><div className="nav-group"><div className="nav-heading">GIÁO VIÊN</div>{teacher ? <><ModuleLink to="/teacher" end>◈ <span>Tổng quan</span></ModuleLink><ModuleLink to="/teacher/questions">☷ <span>Kho câu hỏi</span></ModuleLink><ModuleLink to="/teacher/questions/ai">✦ <span>Tạo câu hỏi AI</span></ModuleLink><ModuleLink to="/teacher/quizzes">▤ <span>Bộ quiz</span></ModuleLink><ModuleLink to="/teacher/assignments">↗ <span>Giao bài tập</span></ModuleLink><ModuleLink to="/teacher/classes">♧ <span>Lớp học</span></ModuleLink><ModuleLink to="/teacher/realtime">◉ <span>Phòng realtime</span></ModuleLink><ModuleLink to="/teacher/reports">▥ <span>Báo cáo</span></ModuleLink></> : <button className="locked-link" onClick={() => openAuth('teacher')}>⌑ <span>Đăng nhập giáo viên</span><small>Khóa</small></button>}</div></nav><div className="sidebar-footer"><span className="status-dot" /> Hệ thống hoạt động</div></aside><main className="app-main"><header className="app-header"><div><span className="breadcrumb">Quizzz</span><span className="route-title">{isTeacherArea ? 'Không gian giáo viên' : 'Không gian học sinh'}</span></div><div className="header-actions"><span className="user-chip">{teacher ? `GV · ${teacher.displayName}` : student ? `HS · ${student.nickname}` : 'Khách'}</span><button className="auth-button" onClick={() => openAuth(teacher ? 'teacher' : 'student')}>{teacher || student ? 'Đổi tài khoản' : 'Đăng nhập'}</button></div></header><div className="page-content"><Notice text={onError.value} onClose={() => onError('')} /><Outlet /></div></main>{authOpen && <AuthModal role={role} setRole={setRole} onClose={() => setAuthOpen(false)} onSuccess={data => { onAuth(data); setAuthOpen(false); navigate(data.teacher ? '/teacher' : '/student'); }} onError={onError} />}</div>; }
function RouterApp() { const [teacher, setTeacher] = useState(null); const [student, setStudent] = useState(null); const [error, setError] = useState(''); useEffect(() => { api('/auth/me').then(x => x.teacher && setTeacher(x.teacher)).catch(() => {}); api('/student/me').then(x => x.student && setStudent(x.student)).catch(() => {}); }, []); const errorHandler = value => setError(typeof value === 'string' ? value : value?.message || 'Có lỗi xảy ra.'); return <HashRouter><RouterShell teacher={teacher} student={student} onAuth={data => { if (data.teacher) setTeacher(data.teacher); if (data.student) setStudent(data.student); }} onError={errorHandler} /><Routes><Route element={<RouterShell teacher={teacher} student={student} onAuth={data => { if (data.teacher) setTeacher(data.teacher); if (data.student) setStudent(data.student); }} onError={errorHandler} />}><Route path="/" element={<Navigate to="/student" replace />} /><Route path="/student" element={<StudentHome onJoin={() => window.location.hash = '#/student/room'} />} /><Route path="/student/room" element={<StudentRoom onError={errorHandler} student={student} />} /><Route path="/student/assignments" element={<StudentAssignments onError={errorHandler} student={student} />} /><Route path="/student/classes" element={<JoinClass onError={errorHandler} student={student} />} /><Route path="/teacher" element={<RoleGuard teacher={teacher}><TeacherHome teacher={teacher} setView={() => {}} /></RoleGuard>} /><Route path="/teacher/questions" element={<RoleGuard teacher={teacher}><Questions onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/questions/ai" element={<RoleGuard teacher={teacher}><AiQuiz onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/quizzes" element={<RoleGuard teacher={teacher}><QuizSets onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/assignments" element={<RoleGuard teacher={teacher}><Assignments onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/classes" element={<RoleGuard teacher={teacher}><Classes onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/realtime" element={<RoleGuard teacher={teacher}><Realtime onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/reports" element={<RoleGuard teacher={teacher}><Reports onError={errorHandler} /></RoleGuard>} /><Route path="*" element={<Navigate to="/student" replace />} /></Route></Routes></HashRouter>; }
function RouterAppFixed() { const [teacher, setTeacher] = useState(null); const [student, setStudent] = useState(null); const [error, setError] = useState(''); useEffect(() => { api('/auth/me').then(x => x.teacher && setTeacher(x.teacher)).catch(() => {}); api('/student/me').then(x => x.student && setStudent(x.student)).catch(() => {}); }, []); const errorHandler = value => setError(typeof value === 'string' ? value : value?.message || 'Có lỗi xảy ra.'); return <HashRouter><Routes><Route element={<RouterShell teacher={teacher} student={student} onAuth={data => { if (data.teacher) setTeacher(data.teacher); if (data.student) setStudent(data.student); }} onError={errorHandler} />}><Route path="/" element={<Navigate to="/student" replace />} /><Route path="/student" element={<StudentHome onJoin={() => window.location.hash = '#/student/room'} />} /><Route path="/student/room" element={<StudentRoom onError={errorHandler} student={student} />} /><Route path="/student/assignments" element={<StudentAssignments onError={errorHandler} student={student} />} /><Route path="/student/classes" element={<JoinClass onError={errorHandler} student={student} />} /><Route path="/teacher" element={<RoleGuard teacher={teacher}><TeacherHome teacher={teacher} setView={() => {}} /></RoleGuard>} /><Route path="/teacher/questions" element={<RoleGuard teacher={teacher}><Questions onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/questions/ai" element={<RoleGuard teacher={teacher}><AiQuiz onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/quizzes" element={<RoleGuard teacher={teacher}><QuizSets onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/assignments" element={<RoleGuard teacher={teacher}><Assignments onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/classes" element={<RoleGuard teacher={teacher}><Classes onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/realtime" element={<RoleGuard teacher={teacher}><Realtime onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/reports" element={<RoleGuard teacher={teacher}><Reports onError={errorHandler} /></RoleGuard>} /><Route path="*" element={<Navigate to="/student" replace />} /></Route></Routes></HashRouter>; }
const nativePushState = window.history.pushState.bind(window.history);
window.history.pushState = (...args) => { nativePushState(...args); window.dispatchEvent(new PopStateEvent('popstate')); };
function LanguageSwitcher() { const { t } = useTranslation(); const [locale, setLocale] = useState(i18n.language?.startsWith('en') ? 'en' : 'vi'); async function change(event) { const next = event.target.value; await i18n.changeLanguage(next); localStorage.setItem('quizzz.locale', next); setLocale(next); } return <label className="language-switcher" title={t('common.language')}><span>文</span><select value={locale} onChange={change} aria-label={t('common.language')}><option value="vi">VI</option><option value="en">EN</option></select></label>; }
function AppProviders() { return <ConfigProvider theme={{ token: { colorPrimary: '#4f46e5', colorInfo: '#4f46e5', borderRadius: 10, fontFamily: "'Plus Jakarta Sans', Inter, system-ui, sans-serif" }, components: { Button: { controlHeight: 40, fontWeight: 700 }, Card: { borderRadiusLG: 16 }, Table: { headerBg: '#f2f3ff' } } }}><QueryClientProvider client={queryClient}><RouterAppFixed /><LanguageSwitcher /><Toaster position="top-right" richColors closeButton /></QueryClientProvider></ConfigProvider>; }
createRoot(document.getElementById('root')).render(<AppProviders />);
